import {wordScenes,newWordGame,wordFeedback,chooseMeaning,chooseClue,checkWordAnswer,showWordHint,selectWordScene,selectWordPage} from './word-game.mjs';
const sceneLabels=['El descanso','En la ciudad','En la mesa','La celebración','Junto a la ventana','En el edificio'];
const pictureLabels=['Una persona descansa en un asiento largo de un parque, cerca de un árbol.','Una familia frente a un edificio con una ventanilla y monedas dibujadas.','Una mesa con un recipiente con pie que contiene agua, junto a una jarra.','Un trofeo con asas y estrella sobre una base, durante una celebración.','Un vegetal con hojas crece en una maceta junto a una ventana.','Un edificio de tres pisos numerados. Una persona está en el segundo.'];
function sceneArt(index,emphasis){
 const defs='<defs><linearGradient id="word-sky" x2="0" y2="1"><stop stop-color="#e5eff1"/><stop offset="1" stop-color="#f6f2df"/></linearGradient></defs>';
 const common='<rect width="600" height="280" rx="20" fill="url(#word-sky)"/><circle cx="507" cy="48" r="23" fill="#efc978"/><path d="M0 232Q150 213 300 234T600 224V280H0Z" fill="#cadbbd"/>';
 const highlight=emphasis?' stroke="#885527" stroke-width="4" stroke-dasharray="7 5"':'';
 const arts=[
 `<path d="M93 230V90" stroke="#866149" stroke-width="20"/><circle cx="93" cy="80" r="54" fill="#91b393"/><circle cx="130" cy="103" r="43" fill="#aac59c"/><g${highlight}><rect x="223" y="139" width="255" height="27" rx="7" fill="#b98559"/><rect x="210" y="180" width="279" height="17" rx="6" fill="#c79963"/><path d="M243 197v43M450 197v43" stroke="#4e6856" stroke-width="12"/></g><circle cx="292" cy="101" r="20" fill="#b98162"/><path d="M285 125v57h48v46" fill="none" stroke="#407b80" stroke-width="27" stroke-linecap="round"/><path d="M275 134l-28 34" stroke="#b98162" stroke-width="13" stroke-linecap="round"/>`,
 `<g${highlight}><path d="M179 95l121-54 121 54z" fill="#638b97"/><rect x="184" y="101" width="233" height="127" rx="7" fill="#e8d5ab"/><rect x="202" y="116" width="194" height="46" rx="6" fill="#fbf7e9"/><circle cx="244" cy="139" r="12" fill="#c7983e"/><circle cx="271" cy="139" r="12" fill="#ddb555"/><rect x="306" y="176" width="70" height="52" fill="#6d8c8a"/><path d="M214 178v40M242 178v40" stroke="#a3b7b0" stroke-width="17"/></g><circle cx="134" cy="181" r="16" fill="#ae7454"/><path d="M134 205v45" stroke="#6d7899" stroke-width="22" stroke-linecap="round"/><circle cx="454" cy="184" r="15" fill="#ca916c"/><path d="M454 207v43" stroke="#d39169" stroke-width="20" stroke-linecap="round"/>`,
 `<path d="M93 199h410v29H93z" fill="#bb875b"/><path d="M121 225v39M474 225v39" stroke="#8e6549" stroke-width="13"/><g${highlight}><path d="M205 65h118l-14 70q-10 31-45 31t-45-31z" fill="#d9e9e6" stroke="#6d9598" stroke-width="5"/><path d="M216 111h98l-9 28q-13 25-41 25t-40-25z" fill="#92c3cf"/><path d="M264 167v30m-33 2h65" fill="none" stroke="#60888b" stroke-width="7" stroke-linecap="round"/></g><path d="M392 79h62v92h-78V103l16-12z" fill="#aecfce"/><path d="M453 97q49-4 42 35t-40 15" fill="none" stroke="#749d9d" stroke-width="9"/>`,
 `<g${highlight}><path d="M234 67h132l-14 75q-8 39-52 39t-52-39z" fill="#e3b451"/><path d="M236 85h-37q-3 66 53 58M365 85h36q3 66-52 58" fill="none" stroke="#bc8e39" stroke-width="13"/><path d="M300 179v32" stroke="#c69b44" stroke-width="21"/><rect x="253" y="206" width="94" height="16" rx="6" fill="#d7a84c"/><rect x="239" y="226" width="122" height="27" rx="5" fill="#738b80"/><path d="m300 92 8 17 19 3-14 13 3 19-16-9-16 9 3-19-14-13 19-3z" fill="#fff0b8"/></g><path d="m110 86 12 18m361 56 12-14m-48-93 14 12M154 183l-15 9" stroke="#d19c86" stroke-width="8" stroke-linecap="round"/>`,
 `<rect x="363" y="28" width="147" height="156" rx="7" fill="#fbf8e9" stroke="#98bab7" stroke-width="9"/><path d="M435 30v153m-69-78h140" stroke="#98bab7" stroke-width="7"/><g${highlight}><path d="M183 166h116l-18 81h-80z" fill="#c88e6b"/><path d="M241 173V76" stroke="#608762" stroke-width="8"/><path d="M240 123q-85-10-73-56 72 0 73 56M243 102q9-69 69-56 4 51-69 56M240 157q-54-3-65-34 51-18 65 34M246 146q62-54 88-22-26 38-88 22" fill="#8baa78"/></g>`,
 `<rect x="184" y="28" width="236" height="220" rx="9" fill="#c7d6cf"/><path d="M178 248h249" stroke="#839b8c" stroke-width="9"/><g fill="#edf3e9"><rect x="211" y="48" width="178" height="49" rx="5"/><rect x="211" y="111" width="178" height="49" rx="5"/><rect x="211" y="175" width="178" height="49" rx="5"/></g><rect x="205" y="105" width="190" height="61" rx="9" fill="none"${highlight}/><g font-family="sans-serif" font-size="27" fill="#466453"><text x="158" y="82">3</text><text x="158" y="146">2</text><text x="158" y="211">1</text></g><circle cx="299" cy="130" r="10" fill="#b68060"/><path d="M299 144v13" stroke="#537f90" stroke-width="17"/><path d="M237 57v31m117-31v31m-117 96v30m117-30v30" stroke="#a8c3c0" stroke-width="17"/>`
 ];
 return `<svg viewBox="0 0 600 280" role="img" aria-label="${pictureLabels[index]}">${defs}${common}${arts[index]}</svg>`;
}
export function renderWordGame(root,state,onFinish){
 state.words??=newWordGame();const game=state.words;
 const draw=(focusId)=>{
  const scene=wordScenes[game.scene],answer=game.answers[game.scene];
  const correct=answer.checked&&answer.meaning===scene.meaning&&scene.fragments.some(f=>f.id===answer.clue&&f.clue);
  root.innerHTML=`<section class="word-game" aria-label="La palabra escondida"><nav class="word-pages" aria-label="Partes de La palabra escondida">${[['scene','Explorar escenas'],['recall','Sin mirar el modelo'],['offscreen','Llevarlo fuera']].map(([id,label])=>`<button type="button" data-word-page="${id}" ${game.page===id?'aria-current="step"':''}>${label}</button>`).join('')}</nav>
  ${game.page==='scene'?`<header class="word-heading"><div><p class="eyebrow">UNA PALABRA · DOS SENTIDOS · 7–8 AÑOS ORIENTATIVOS</p><h5 id="word-title" tabindex="-1">${scene.word.charAt(0).toUpperCase()+scene.word.slice(1)}: mira lo que ocurre</h5><p>Elige un significado. Después, toca las palabras de la frase que te ayudan a decidir.</p></div><span class="word-scene-count">Escena ${game.scene+1} de 6</span></header><div class="word-scene-tabs" role="group" aria-label="Elegir escena">${wordScenes.map((s,i)=>`<button type="button" data-word-scene="${i}" aria-pressed="${game.scene===i}" aria-label="Escena ${i+1}: ${s.word}, ${sceneLabels[i]}">${i+1}<span>${s.word}</span></button>`).join('')}</div>
  <div class="word-workspace"><div class="word-picture">${sceneArt(game.scene,scene.fragments.some(f=>f.id===answer.clue&&f.clue))}<span class="word-picture-label">${sceneLabels[game.scene]}</span></div><div class="word-desk"><div class="word-token">${scene.word}</div><p class="word-instruction"><b>1.</b> Aquí, esta palabra se refiere a…</p><div class="word-meanings" role="group" aria-label="Elegir significado">${scene.options.map(option=>`<button type="button" data-word-meaning="${option.id}" aria-pressed="${answer.meaning===option.id}"><strong>${option.label}</strong><small>${option.description}</small><span>${answer.meaning===option.id?'Elegido':'Elegir este sentido'}</span></button>`).join('')}</div></div><div class="word-clues"><p class="word-instruction"><b>2.</b> Toca una pista dentro de la frase</p><div class="word-sentence" role="group" aria-label="Frase: ${scene.fragments.map(f=>f.text).join(' ')}">${scene.fragments.map(f=>`<button type="button" data-word-clue="${f.id}" aria-pressed="${answer.clue===f.id}">${f.text}</button>`).join('')}</div><p class="quiet">Puedes leerla con ayuda. La explicación se puede decir o señalar, sin grabar.</p></div><div class="word-check"><button type="button" class="action primary" id="word-check">Comprobar palabra y pista</button><button type="button" class="action secondary" id="word-hint">${answer.hint>=scene.hints.length?'Releer la ayuda':answer.hint?'Una ayuda más':'Necesito una pista'}</button></div><p id="word-hint-text" class="word-hint" role="status" aria-live="polite">${answer.hint?scene.hints[answer.hint-1]:''}</p><div id="word-feedback" class="word-feedback ${correct?'word-connected':''}" role="status" aria-live="polite" aria-atomic="true">${wordFeedback(game)}</div></div><div class="word-next"><p>${correct?'Has relacionado la escena, el significado y una pista. Puedes parar o mirar otro contexto.':'Puedes cambiar de escena o terminar cuando quieras. No necesitas acertar para seguir.'}</p><button type="button" class="action secondary" id="word-next">${game.scene<5?'Otra escena →':'Si quieres: recordar sin modelo'}</button></div><details class="word-coach"><summary>Para quien acompaña: una pregunta útil</summary><p>${scene.coach}</p><p>Lee sin destacar la respuesta al principio. Si hace falta, señala una sola pista y vuelve a dejar espacio. Una elección entre opciones es reconocimiento, no una prueba de recuerdo libre.</p></details>`:
  game.page==='recall'?`<div class="word-recall"><p class="eyebrow">UNA PAUSA PARA RECORDAR</p><h5 id="word-title" tabindex="-1">La misma palabra, dos dibujos.</h5><p>Sin volver a las escenas, elige una palabra y cuenta o dibuja sus dos sentidos.</p><div class="word-memory-tokens"><span>banco</span><span>copa</span><span>planta</span></div><p>Puedes hacerlo hablando, con gestos o con papel. No se graba ni se califica. Si todavía no lo recuerdas, mirar una ayuda también sirve.</p><button type="button" class="action secondary" id="word-recall-model" aria-expanded="${game.recallShown}">${game.recallShown?'Ocultar el modelo':'Ver los dos sentidos'}</button>${game.recallShown?`<div class="word-recall-model">${[0,2,4].map(i=>`<article><strong>${wordScenes[i].word}</strong><p>${wordScenes[i].options.map(o=>o.label).join(' · ')}</p></article>`).join('')}</div>`:''}<p class="quiet">Recordar aquí no demuestra retención a largo plazo. Otro día pueden inventar una frase nueva, si apetece, sin avisos ni obligación de volver.</p><button type="button" class="action primary" data-word-page="offscreen">Una idea fuera de pantalla →</button></div>`:
  `<div class="word-offscreen"><p class="word-session-summary">Revisaste elecciones en ${game.answers.filter(a=>a.checked).length} escenas y consultaste ayuda en ${game.answers.filter(a=>a.hint>0).length}. Describe participación, no dominio de las palabras.</p><p class="eyebrow">DOS ESCENAS EN TU MUNDO</p><h5 id="word-title" tabindex="-1">¿Qué copa estás imaginando?</h5><div class="word-paper"><span>beber</span><b>copa</b><span>recibir un trofeo</span></div><p>Dibujad dos escenas distintas con «copa». Quien mira cuenta qué detalle le ayuda a distinguirlas.</p><p>Sin materiales: haz el gesto de beber y luego de recibir un trofeo. Basta imaginarlo; no uses cristal ni hace falta buscar objetos.</p><details class="word-coach"><summary>Para quien acompaña</summary><p>Pregunta «¿qué pista te ayudó?». Acepta palabras, gestos o dibujos y sigue su iniciativa. Hacer la actividad no demuestra por sí solo que ya transfiera lo aprendido.</p></details><div class="word-participation" role="group" aria-label="Actividad fuera de pantalla, declaración opcional">${[['untried','Aún no la probamos'],['planned','La dejamos para luego'],['tried','La probamos juntos']].map(([id,label])=>`<button type="button" class="action secondary" data-word-offscreen="${id}" aria-pressed="${game.offscreen===id}">${label}</button>`).join('')}</div><p class="quiet">Esta marca solo recuerda participación en este navegador; no mide aprendizaje.</p><button type="button" class="action primary" id="word-finish">Guardar la pantalla y terminar</button></div>`}
  <details class="word-evidence"><summary>Por qué esta actividad</summary><p>Diseño informado por investigación; esta actividad todavía no se ha evaluado en un estudio propio.</p><p>Ensayos con niños de 7–8 años estudiaron significados de palabras enseñadas, con transferencia limitada a otras palabras. Esta adaptación en español no está validada por Oxford ni Harvard.</p><p><a href="https://doi.org/10.1111/bjep.70056" target="_blank" rel="noopener">Estudio de palabras con varios significados</a> · <a href="https://developingchild.harvard.edu/resources/handouts-tools/brainbuildingthroughplay/" target="_blank" rel="noopener">Juego acompañado por edades</a></p></details></section>`;
  const bind=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>fn(el)));
  bind('[data-word-page]',el=>{selectWordPage(game,el.dataset.wordPage);draw('word-title');});
  bind('[data-word-scene]',el=>{selectWordScene(game,Number(el.dataset.wordScene));draw('word-title');});
  bind('[data-word-meaning]',el=>{chooseMeaning(game,el.dataset.wordMeaning);draw();root.querySelector(`[data-word-meaning="${el.dataset.wordMeaning}"]`)?.focus({preventScroll:true});});
  bind('[data-word-clue]',el=>{chooseClue(game,el.dataset.wordClue);draw();root.querySelector(`[data-word-clue="${el.dataset.wordClue}"]`)?.focus({preventScroll:true});});
  bind('#word-check',()=>{const complete=checkWordAnswer(game);draw('word-check');if(!complete){root.querySelector('#word-feedback').textContent='Falta elegir un significado y una pista. Toca ambos antes de comprobar.';}});
  bind('#word-hint',()=>{showWordHint(game);draw('word-hint');});
  bind('#word-next',()=>{if(game.scene<5)selectWordScene(game,game.scene+1);else selectWordPage(game,'recall');draw('word-title');});
  bind('#word-recall-model',()=>{game.recallShown=!game.recallShown;draw('word-recall-model');});
  bind('[data-word-offscreen]',el=>{game.offscreen=el.dataset.wordOffscreen;draw();root.querySelector(`[data-word-offscreen="${game.offscreen}"]`)?.focus({preventScroll:true});});
  bind('#word-finish',onFinish);
  if(focusId)root.querySelector('#'+focusId)?.focus({preventScroll:focusId!=='word-title'});
 };
 draw();
}
